def features(timestamps, covariates, context_length):
    d = pd.DatetimeIndex(timestamps)
    dow = np.asarray(d.dayofweek, dtype=int)
    names = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']
    result = {}
    for i, nm in enumerate(names):
        ind = (dow == i).astype(float)
        # Center using the context prefix only so channels are ~zero-mean
        # and the one-hot set is not collinear with a constant level.
        if context_length > 0:
            mu = float(ind[:context_length].mean())
        else:
            mu = 1.0 / 7.0
        result['day_' + nm] = ind - mu
    return result
